get_category_page.code:
var response = await client.CategoryPage.GetCategoryPageAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var categoryPage = (IReadOnlyDictionary<string, object?>)body["category_page"]!;
var categoryInformation = (IReadOnlyDictionary<string, object?>)categoryPage["category_information"]!;
Console.WriteLine(categoryInformation["show_description"]);

patch_category_page.code:
var response = await client.CategoryPage.PatchCategoryPageAsync(new Dictionary<string, object?>
{
    ["category_page"] = new Dictionary<string, object?>
    {
        ["category_information"] = new Dictionary<string, object?>
        {
            ["show_description"] = true, ["subcategory"] = new Dictionary<string, object?> { ["per_page"] = 24 },
        },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var categoryPage = (IReadOnlyDictionary<string, object?>)body["category_page"]!;
var categoryInformation = (IReadOnlyDictionary<string, object?>)categoryPage["category_information"]!;
Console.WriteLine(categoryInformation["show_description"]);

